-- ============================================================
-- LEAVE MANAGEMENT
-- ============================================================

CREATE TABLE IF NOT EXISTS leave_types (
  id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id   BIGINT NOT NULL REFERENCES companies(id),
  name         VARCHAR(100) NOT NULL,
  description  TEXT,
  days_per_year NUMERIC(5,2) NOT NULL DEFAULT 0,
  carry_forward BOOLEAN NOT NULL DEFAULT FALSE,
  max_carry_forward_days NUMERIC(5,2) DEFAULT 0,
  applicable_gender VARCHAR(10) DEFAULT 'All'
                     CHECK (applicable_gender IN ('All','Male','Female','Other')),
  is_paid      BOOLEAN NOT NULL DEFAULT TRUE,
  status       VARCHAR(20) NOT NULL DEFAULT 'Active'
               CHECK (status IN ('Active','Inactive')),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (company_id, name)
);

CREATE INDEX IF NOT EXISTS idx_leave_types_company ON leave_types(company_id);

-- Per-employee leave balance (per leave-type per calendar year)
CREATE TABLE IF NOT EXISTS leave_balances (
  id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id      BIGINT NOT NULL REFERENCES companies(id),
  employee_id     BIGINT NOT NULL REFERENCES employees(id),
  leave_type_id   BIGINT NOT NULL REFERENCES leave_types(id),
  year            INT NOT NULL,
  allocated       NUMERIC(7,2) NOT NULL DEFAULT 0,
  used            NUMERIC(7,2) NOT NULL DEFAULT 0,
  carry_forward   NUMERIC(7,2) NOT NULL DEFAULT 0,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (company_id, employee_id, leave_type_id, year)
);

CREATE INDEX IF NOT EXISTS idx_leave_balances_employee ON leave_balances(employee_id);

-- Leave requests submitted by employees
CREATE TABLE IF NOT EXISTS leave_requests (
  id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id      BIGINT NOT NULL REFERENCES companies(id),
  employee_id     BIGINT NOT NULL REFERENCES employees(id),
  leave_type_id   BIGINT NOT NULL REFERENCES leave_types(id),
  from_date       DATE NOT NULL,
  to_date         DATE NOT NULL,
  days            NUMERIC(5,2) NOT NULL,
  reason          TEXT,
  status          VARCHAR(20) NOT NULL DEFAULT 'Pending'
                  CHECK (status IN ('Pending','Approved','Rejected','Cancelled')),
  reviewed_by     BIGINT REFERENCES users(id),
  reviewed_at     TIMESTAMPTZ,
  review_note     TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT leave_dates_check CHECK (to_date >= from_date)
);

CREATE INDEX IF NOT EXISTS idx_leave_requests_company_employee ON leave_requests(company_id, employee_id);
CREATE INDEX IF NOT EXISTS idx_leave_requests_status ON leave_requests(company_id, status);

-- Holiday calendar
CREATE TABLE IF NOT EXISTS holidays (
  id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id   BIGINT NOT NULL REFERENCES companies(id),
  name         VARCHAR(200) NOT NULL,
  holiday_date DATE NOT NULL,
  type         VARCHAR(30) NOT NULL DEFAULT 'National'
               CHECK (type IN ('National','Regional','Company','Restricted')),
  location     VARCHAR(200) DEFAULT 'All Locations',
  description  TEXT,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (company_id, holiday_date, name)
);

CREATE INDEX IF NOT EXISTS idx_holidays_company_date ON holidays(company_id, holiday_date);

-- ============================================================
-- ATTENDANCE MANAGEMENT
-- ============================================================

CREATE TABLE IF NOT EXISTS shifts (
  id                   BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id           BIGINT NOT NULL REFERENCES companies(id),
  name                 VARCHAR(100) NOT NULL,
  start_time           TIME NOT NULL,
  end_time             TIME NOT NULL,
  grace_minutes        INT NOT NULL DEFAULT 15,
  break_minutes        INT NOT NULL DEFAULT 60,
  overtime_threshold   INT NOT NULL DEFAULT 30,
  weekly_off           VARCHAR(20) DEFAULT 'Sunday',
  location             VARCHAR(200) DEFAULT 'All Locations',
  status               VARCHAR(20) NOT NULL DEFAULT 'Active'
                       CHECK (status IN ('Active','Inactive')),
  created_at           TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (company_id, name)
);

CREATE INDEX IF NOT EXISTS idx_shifts_company ON shifts(company_id);

-- Biometric/access devices
CREATE TABLE IF NOT EXISTS biometric_devices (
  id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id   BIGINT NOT NULL REFERENCES companies(id),
  device_name  VARCHAR(200) NOT NULL,
  brand        VARCHAR(100),
  model        VARCHAR(100),
  location     VARCHAR(200),
  connection_type VARCHAR(30) DEFAULT 'LAN'
               CHECK (connection_type IN ('LAN','WiFi','Cloud','Serial')),
  ip_address   VARCHAR(50),
  serial_number VARCHAR(100),
  status       VARCHAR(30) NOT NULL DEFAULT 'Unknown'
               CHECK (status IN ('Online','Offline','Unknown','Maintenance')),
  last_sync_at TIMESTAMPTZ,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (company_id, device_name)
);

CREATE INDEX IF NOT EXISTS idx_biometric_devices_company ON biometric_devices(company_id);

-- Raw biometric punch records
CREATE TABLE IF NOT EXISTS raw_punches (
  id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id      BIGINT NOT NULL REFERENCES companies(id),
  device_id       BIGINT REFERENCES biometric_devices(id),
  employee_id     BIGINT REFERENCES employees(id),
  punch_time      TIMESTAMPTZ NOT NULL,
  punch_type      VARCHAR(10) DEFAULT 'Unknown'
                  CHECK (punch_type IN ('In','Out','Break','Unknown')),
  device_user_id  VARCHAR(100),
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_raw_punches_employee_time ON raw_punches(employee_id, punch_time);
CREATE INDEX IF NOT EXISTS idx_raw_punches_company_time ON raw_punches(company_id, punch_time);

-- Daily processed attendance records
CREATE TABLE IF NOT EXISTS attendance_records (
  id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id      BIGINT NOT NULL REFERENCES companies(id),
  employee_id     BIGINT NOT NULL REFERENCES employees(id),
  shift_id        BIGINT REFERENCES shifts(id),
  attendance_date DATE NOT NULL,
  check_in        TIMESTAMPTZ,
  check_out       TIMESTAMPTZ,
  status          VARCHAR(30) NOT NULL DEFAULT 'Absent'
                  CHECK (status IN ('Present','Absent','Late','Half Day','On Leave','Holiday','Missing Punch')),
  working_minutes INT,
  overtime_minutes INT DEFAULT 0,
  is_regularized  BOOLEAN NOT NULL DEFAULT FALSE,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (company_id, employee_id, attendance_date)
);

CREATE INDEX IF NOT EXISTS idx_attendance_company_date ON attendance_records(company_id, attendance_date);
CREATE INDEX IF NOT EXISTS idx_attendance_employee_date ON attendance_records(employee_id, attendance_date);

-- Attendance regularization requests
CREATE TABLE IF NOT EXISTS attendance_regularizations (
  id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id      BIGINT NOT NULL REFERENCES companies(id),
  employee_id     BIGINT NOT NULL REFERENCES employees(id),
  attendance_date DATE NOT NULL,
  requested_check_in  TIMESTAMPTZ,
  requested_check_out TIMESTAMPTZ,
  reason          TEXT,
  status          VARCHAR(20) NOT NULL DEFAULT 'Pending'
                  CHECK (status IN ('Pending','Approved','Rejected')),
  reviewed_by     BIGINT REFERENCES users(id),
  reviewed_at     TIMESTAMPTZ,
  review_note     TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_regularizations_company ON attendance_regularizations(company_id, status);

-- Roster: employee shift assignments
CREATE TABLE IF NOT EXISTS rosters (
  id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id   BIGINT NOT NULL REFERENCES companies(id),
  employee_id  BIGINT NOT NULL REFERENCES employees(id),
  shift_id     BIGINT NOT NULL REFERENCES shifts(id),
  effective_from DATE NOT NULL,
  effective_to   DATE,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_rosters_company_employee ON rosters(company_id, employee_id);

-- ============================================================
-- PAYROLL
-- ============================================================

-- Salary components (e.g., Basic, HRA, PF, TDS)
CREATE TABLE IF NOT EXISTS salary_components (
  id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id   BIGINT NOT NULL REFERENCES companies(id),
  name         VARCHAR(100) NOT NULL,
  component_type VARCHAR(20) NOT NULL DEFAULT 'Earning'
               CHECK (component_type IN ('Earning','Deduction','Employer Contribution')),
  calculation_type VARCHAR(20) NOT NULL DEFAULT 'Fixed'
               CHECK (calculation_type IN ('Fixed','Percentage')),
  -- If percentage, the percentage value; if fixed, leave null
  percentage_of VARCHAR(100),
  is_statutory BOOLEAN NOT NULL DEFAULT FALSE,
  -- NOTE: statutory rates must be confirmed per applicable law
  -- Values here are indicative placeholders; confirm with your
  -- payroll accountant before using in production payroll runs.
  status       VARCHAR(20) NOT NULL DEFAULT 'Active'
               CHECK (status IN ('Active','Inactive')),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (company_id, name)
);

CREATE INDEX IF NOT EXISTS idx_salary_components_company ON salary_components(company_id);

-- Salary structures (templates)
CREATE TABLE IF NOT EXISTS salary_structures (
  id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id   BIGINT NOT NULL REFERENCES companies(id),
  name         VARCHAR(200) NOT NULL,
  description  TEXT,
  ctc_min      NUMERIC(15,2),
  ctc_max      NUMERIC(15,2),
  status       VARCHAR(20) NOT NULL DEFAULT 'Active'
               CHECK (status IN ('Active','Inactive')),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (company_id, name)
);

CREATE INDEX IF NOT EXISTS idx_salary_structures_company ON salary_structures(company_id);

-- Salary structure components (which components and at what amounts/percentages)
CREATE TABLE IF NOT EXISTS salary_structure_components (
  id                   BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  structure_id         BIGINT NOT NULL REFERENCES salary_structures(id) ON DELETE CASCADE,
  component_id         BIGINT NOT NULL REFERENCES salary_components(id),
  amount               NUMERIC(15,2),
  percentage           NUMERIC(7,4),
  UNIQUE (structure_id, component_id)
);

-- Employee salary assignments
CREATE TABLE IF NOT EXISTS employee_salary_assignments (
  id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id      BIGINT NOT NULL REFERENCES companies(id),
  employee_id     BIGINT NOT NULL REFERENCES employees(id),
  structure_id    BIGINT NOT NULL REFERENCES salary_structures(id),
  ctc_annual      NUMERIC(15,2) NOT NULL,
  effective_from  DATE NOT NULL,
  effective_to    DATE,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_emp_salary_assignments_employee ON employee_salary_assignments(employee_id);

-- Payroll runs (one per pay period per company)
CREATE TABLE IF NOT EXISTS payroll_runs (
  id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id      BIGINT NOT NULL REFERENCES companies(id),
  pay_period_year INT NOT NULL,
  pay_period_month INT NOT NULL CHECK (pay_period_month BETWEEN 1 AND 12),
  status          VARCHAR(30) NOT NULL DEFAULT 'Draft'
                  CHECK (status IN ('Draft','Processing','Completed','Cancelled')),
  processed_by    BIGINT REFERENCES users(id),
  processed_at    TIMESTAMPTZ,
  total_gross     NUMERIC(18,2),
  total_net       NUMERIC(18,2),
  total_deductions NUMERIC(18,2),
  notes           TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (company_id, pay_period_year, pay_period_month)
);

CREATE INDEX IF NOT EXISTS idx_payroll_runs_company ON payroll_runs(company_id);

-- Individual payslips (one per employee per payroll run)
CREATE TABLE IF NOT EXISTS payslips (
  id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  payroll_run_id  BIGINT NOT NULL REFERENCES payroll_runs(id) ON DELETE CASCADE,
  company_id      BIGINT NOT NULL REFERENCES companies(id),
  employee_id     BIGINT NOT NULL REFERENCES employees(id),
  basic_pay       NUMERIC(15,2) NOT NULL DEFAULT 0,
  hra             NUMERIC(15,2) NOT NULL DEFAULT 0,
  da              NUMERIC(15,2) NOT NULL DEFAULT 0,
  other_earnings  NUMERIC(15,2) NOT NULL DEFAULT 0,
  gross_pay       NUMERIC(15,2) NOT NULL DEFAULT 0,
  pf_employee     NUMERIC(15,2) NOT NULL DEFAULT 0,
  esic_employee   NUMERIC(15,2) NOT NULL DEFAULT 0,
  professional_tax NUMERIC(15,2) NOT NULL DEFAULT 0,
  tds             NUMERIC(15,2) NOT NULL DEFAULT 0,
  other_deductions NUMERIC(15,2) NOT NULL DEFAULT 0,
  total_deductions NUMERIC(15,2) NOT NULL DEFAULT 0,
  net_salary      NUMERIC(15,2) NOT NULL DEFAULT 0,
  -- Employer contributions (not deducted from employee but recorded)
  pf_employer     NUMERIC(15,2) NOT NULL DEFAULT 0,
  esic_employer   NUMERIC(15,2) NOT NULL DEFAULT 0,
  working_days    INT,
  paid_days       INT,
  lop_days        NUMERIC(5,2) DEFAULT 0,
  status          VARCHAR(20) NOT NULL DEFAULT 'Draft'
                  CHECK (status IN ('Draft','Generated','Disbursed')),
  -- Calculation details in JSON for audit trail
  calculation_detail JSONB,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (payroll_run_id, employee_id)
);

CREATE INDEX IF NOT EXISTS idx_payslips_company_employee ON payslips(company_id, employee_id);
CREATE INDEX IF NOT EXISTS idx_payslips_run ON payslips(payroll_run_id);

-- Employee advances (salary loans)
CREATE TABLE IF NOT EXISTS employee_advances (
  id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  company_id      BIGINT NOT NULL REFERENCES companies(id),
  employee_id     BIGINT NOT NULL REFERENCES employees(id),
  amount          NUMERIC(15,2) NOT NULL,
  purpose         TEXT,
  emi_amount      NUMERIC(15,2),
  balance         NUMERIC(15,2) NOT NULL,
  status          VARCHAR(20) NOT NULL DEFAULT 'Pending'
                  CHECK (status IN ('Pending','Approved','Active','Closed','Rejected')),
  approved_by     BIGINT REFERENCES users(id),
  approved_at     TIMESTAMPTZ,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_advances_company_employee ON employee_advances(company_id, employee_id);

-- ============================================================
-- Comments on statutory rates (IMPORTANT)
-- ============================================================
-- PF: Employee contribution 12% of PF wage; Employer: 12% of PF wage
--     (8.33% to EPS capped, 3.67% to EPF, plus admin charges)
--     Current statutory rate: as per EPF & MP Act, 1952
--     THESE RATES MUST BE CONFIRMED with your payroll accountant.
--
-- ESIC: Employee 0.75% of gross wages; Employer 3.25% of gross wages
--       Applies to employees with gross <= INR 21,000/month
--       (threshold and rates as of last review; verify current rates)
--       THESE RATES MUST BE CONFIRMED with your payroll accountant.
--
-- Professional Tax: State-specific; varies by state and income slab.
--                   Must be configured per state for your employees.
-- ============================================================
